<?php
public function column_custom_fields($item)
{
    $customFields = unserialize($item['custom_fields']);

    if (is_array($customFields)) {
        foreach ($customFields as $key => $value) {
            printf('<div class="wpsms-custom-field"><strong>%s</strong>: %s</div>', $key, $value);
        }
    }
}
public function column_cb($item)
{
    return sprintf(
        '<input type="checkbox" name="%1$s[]" value="%2$s" />',
        /*$1%s*/
        $this->_args['singular'],  //Let's simply repurpose the table's singular label ("movie")
        /*$2%s*/
        $item['ID']                //The value of the checkbox should be the record's id
    );
}
public function get_bulk_actions()
{
    $actions = ['bulk_delete' => __('Delete', 'wp-sms')];

    $groups = $this->db->get_results("SELECT * FROM `{$this->tb_prefix}sms_subscribes_group`", ARRAY_A);
    if (count($groups)) {
        foreach ($groups as $value) {
            $actions['move_to_' . $value['ID']] = sprintf(__('Move to «%s»', 'wp-sms'), $value['name']);
        }
    }
    return $actions;
}
/**
 * Usort Function
 *
 * @param $a
 * @param $b
 *
 * @return array
 */
public function usort_reorder($a, $b)
{
    $orderby = (!empty($_REQUEST['orderby'])) ? sanitize_text_field($_REQUEST['orderby']) : 'date'; //If no sort, default to sender
    $order   = (!empty($_REQUEST['order'])) ? sanitize_text_field($_REQUEST['order']) : 'desc'; //If no order, default to asc
    $result  = strcmp($a[$orderby], $b[$orderby]); //Determine sort order

    return ($order === 'asc') ? $result : -$result; //Send final sort direction to usort
}
public function mobile_or_country_query($where)
{
    if (isset($_GET['group_id']) && $_GET['group_id']) {
        $group_id = sanitize_text_field($_GET['group_id']);
        $where = "WHERE group_ID = {$group_id}";
    }

    if (isset($_GET['country_code']) && $_GET['country_code']) {
        $country_code = sanitize_text_field($_GET['country_code']);
        if ($where) {
            $where .= " AND mobile LIKE '{$country_code}%'";
        } else {
            $where = "WHERE mobile LIKE '{$country_code}%'";
        }
    }
    return $where;
}
public function column_default($item, $column_name)
{
    switch ($column_name) {
        case 'name':
        case 'mobile':
            return wp_sms_render_quick_reply($item['mobile']);
        case 'activate_key':
            return $item[$column_name];

        case 'group_ID':
            $group = Newsletter::getGroup($item[$column_name]);
            if ($group) {
                return $group->name;
            } else {
                return '-';
            }

        case 'date':
            return sprintf(__('%s <span class="wpsms-time">%s</span>', 'wp-sms'), date_i18n('Y-m-d', strtotime($item[$column_name])), date_i18n('H:i', strtotime($item[$column_name])));

        default:
            return print_r($item, true); //Show the whole array for troubleshooting purposes
    }
}
public function column_status($item)
{
    return Helper::loadTemplate('admin/label-button.php', array(
        'type'  => ($item['status'] == '1' ? 'active' : 'inactive'),
        'label' => ($item['status'] == '1' ? __('Active', 'wp-sms') : __('Inactive', 'wp-sms'))
    ));
}
//get total items on different Queries
public function get_total($query = '')
{
    if (!$query) {
        $query = 'SELECT * FROM `' . $this->tb_prefix . 'sms_subscribes`';
    }

    $result = $this->db->get_results($query, ARRAY_A);

    return count($result);
}
/**
 * @param $which
 * @return void
 */
protected function extra_tablenav($which)
{
    switch ($which) {
        case 'top':

            // Filter by Group
            echo Helper::loadTemplate('admin/group-filter.php', array(
                'groups'   => Newsletter::getGroups(),
                'selected' => (isset($_GET['group_id']) ? $_GET['group_id'] : '')
            ));

            // Filter by Country
            echo Helper::loadTemplate('admin/country-filter.php', array(
                'countries' => Newsletter::filterSubscribersByCountry(),
                'selected'  => (isset($_GET['country_code']) ? $_GET['country_code'] : '')
            ));

            break;
    }
}

