<?php

public function mobile_or_country_query($where)
{
    if (isset($_GET['group_id']) && $_GET['group_id']) {
        $group_id = sanitize_text_field($_GET['group_id']);
        $where = "WHERE group_ID = {$group_id}";
    }

    if (isset($_GET['country_code']) && $_GET['country_code']) {
        $country_code = sanitize_text_field($_GET['country_code']);
        if ($where) {
            $where .= " AND mobile LIKE '{$country_code}%'";
        } else {
            $where = "WHERE mobile LIKE '{$country_code}%'";
        }
    }
    return $where;
}
namespace WP_SMS;

if (!defined('ABSPATH')) {
    exit;
} // Exit if accessed directly

if (!class_exists('WP_List_Table')) {
    require_once(ABSPATH . 'wp-admin/includes/class-wp-list-table.php');
}
public function __construct()
{
    global $wpdb;

    //Set parent defaults
    parent::__construct(array(
        'singular' => 'ID',     //singular name of the listed records
        'plural'   => 'ID',    //plural name of the listed records
        'ajax'     => false        //does this table support ajax?
    ));

    $this->db        = $wpdb;
    $this->tb_prefix = $wpdb->prefix;
    $this->count     = $this->get_total();
    $this->limit     = $this->get_items_per_page('wp_sms_subscriber_per_page');
    $this->data      = $this->get_data();
    $this->adminUrl  = admin_url('admin.php?page=wp-sms-subscribers');
}
public function column_default($item, $column_name)
{
    switch ($column_name) {
        case 'name':
        case 'mobile':
            return wp_sms_render_quick_reply($item['mobile']);
        case 'activate_key':
            return $item[$column_name];

        case 'group_ID':
            $group = Newsletter::getGroup($item[$column_name]);
            if ($group) {
                return $group->name;
            } else {
                return '-';
            }

        case 'date':
            return sprintf(__('%s <span class="wpsms-time">%s</span>', 'wp-sms'), date_i18n('Y-m-d', strtotime($item[$column_name])), date_i18n('H:i', strtotime($item[$column_name])));

        default:
            return print_r($item, true); //Show the whole array for troubleshooting purposes
    }
}
public function column_name($item)
{
    /**
     * Sanitize the input
     */
    $page = sanitize_text_field($_REQUEST['page']);

    //Build row actions
    $actions = array(
        'edit'   => sprintf('<a href="#" onclick="wp_sms_edit_subscriber(%s)">' . __('Edit', 'wp-sms') . '</a>', $item['ID']),
        'delete' => sprintf('<a href="?page=%s&action=%s&ID=%s">' . __('Delete', 'wp-sms') . '</a>', $page, 'delete', $item['ID']),
    );

    //Return the title contents
    return sprintf('%1$s %3$s',
        /*$1%s*/
        esc_html($item['name']),
        /*$2%s*/
        $item['ID'],
        /*$2%s*/
        $this->row_actions($actions)
    );
}
public function column_custom_fields($item)
{
    $customFields = unserialize($item['custom_fields']);

    if (is_array($customFields)) {
        foreach ($customFields as $key => $value) {
            printf('<div class="wpsms-custom-field"><strong>%s</strong>: %s</div>', $key, $value);
        }
    }
}
public function get_columns()
{
    $columns = array(
        'cb'            => '<input type="checkbox" />', //Render a checkbox instead of text
        'name'          => __('Name', 'wp-sms'),
        'mobile'        => __('Mobile', 'wp-sms'),
        'group_ID'      => __('Group', 'wp-sms'),
        'date'          => __('Date', 'wp-sms'),
        'activate_key'  => __('Activate code', 'wp-sms'),
        'status'        => __('Status', 'wp-sms'),
        'custom_fields' => __('Custom Fields', 'wp-sms'),
    );

    return $columns;
}
public function get_bulk_actions()
{
    $actions = ['bulk_delete' => __('Delete', 'wp-sms')];

    $groups = $this->db->get_results("SELECT * FROM `{$this->tb_prefix}sms_subscribes_group`", ARRAY_A);
    if (count($groups)) {
        foreach ($groups as $value) {
            $actions['move_to_' . $value['ID']] = sprintf(__('Move to «%s»', 'wp-sms'), $value['name']);
        }
    }
    return $actions;
}

