        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (obj == null) {
                return false;
            }
            if (getClass() != obj.getClass()) {
                return false;
            }
            LineCursor other = (LineCursor) obj;
            return Objects.equals(uri, other.uri)
                && lineNumber == other.lineNumber
                && Objects.equals(line, other.line)
