        watermark = 0;
        createReader(fileInput, currentInputUriIterator.next());
    }
private void closeReader() {
        if (currentReader != null) {
            try {
                currentReader.close();
            } catch (IOException e) {
                LOGGER.error("Unable to close reader for " + cursor.uri, e);
            }
            currentReader = null;
        }
    }
@Override
